<?php require 'config/database.php';$pedidos=[];if($_SERVER['REQUEST_METHOD']==='POST'){$q=trim($_POST['q']??'');$s=$pdo->prepare('SELECT p.*,r.titulo FROM pedidos p JOIN rifas r ON r.id=p.rifa_id WHERE p.codigo=? OR p.telefone=? OR p.email=? ORDER BY p.id DESC');$s->execute([$q,$q,$q]);$pedidos=$s->fetchAll();}?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title>Meus bilhetes</title></head><body><main class="wrap"><div class="box"><h1>Meus bilhetes</h1><form method="post"><input name="q" placeholder="Código do pedido, WhatsApp ou e-mail" required><button class="btn">Consultar</button></form></div><?php foreach($pedidos as $p):?><div class="box"><b><?=e($p['titulo'])?></b><p>Pedido <?=e($p['codigo'])?> · <?=e($p['status'])?></p><?php $x=$pdo->prepare('SELECT numero FROM bilhetes WHERE pedido_id=?');$x->execute([$p['id']]);?><p>Números: <?=e(implode(', ',array_column($x->fetchAll(),'numero')))?></p></div><?php endforeach;?></main></body></html>
